import { useEffect, useRef } from 'react';

const IW = 320;
const IH = 761;
const FRESCO_B64 = '';

const GRID  = 4;
const MAX_R = GRID * 0.58;

interface Dot {
  x: number; y: number;
  baseR: number; phase: number;
}

export default function CrowdFragment({ className }: { className?: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d')!;

    const CW = canvas.width  = canvas.offsetWidth  || 200;
    const CH = canvas.height = canvas.offsetHeight || 480;

    let animId: number;
    const dots: Dot[] = [];
    let frame = 0;
    let mouseX = -999, mouseY = -999;
    let isHover = false;

    const onMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouseX = (e.clientX - rect.left) * (CW / rect.width);
      mouseY = (e.clientY - rect.top)  * (CH / rect.height);
    };
    const onEnter = () => { isHover = true; };
    const onLeave = () => { isHover = false; mouseX = -999; mouseY = -999; };
    canvas.addEventListener('mousemove', onMove);
    canvas.addEventListener('mouseenter', onEnter);
    canvas.addEventListener('mouseleave', onLeave);

    let pulses: Array<{ r: number; alpha: number }> = [];
    let nextPulse = 300 + Math.floor(Math.random() * 180);

    const img = new Image();
    img.onload = () => {
      const oc = document.createElement('canvas');
      oc.width = IW; oc.height = IH;
      const ox = oc.getContext('2d')!;
      ox.fillStyle = '#000000';
      ox.fillRect(0, 0, IW, IH);
      ox.drawImage(img, 0, 0, IW, IH);
      const px = ox.getImageData(0, 0, IW, IH).data;

      const scale = Math.min(CW / IW, CH / IH) * 0.94;
      const dw  = IW * scale;
      const dh  = IH * scale;
      const ox0 = (CW - dw) / 2;
      const oy0 = (CH - dh) / 2;

      for (let py = GRID / 2; py < CH; py += GRID) {
        for (let pxx = GRID / 2; pxx < CW; pxx += GRID) {
          const ix = Math.round((pxx - ox0) / scale);
          const iy = Math.round((py  - oy0) / scale);
          if (ix < 0 || iy < 0 || ix >= IW || iy >= IH) continue;
          const i   = (iy * IW + ix) * 4;
          const lum = (px[i]*0.299 + px[i+1]*0.587 + px[i+2]*0.114) / 255;
          if (lum < 0.08) continue;
          const r = lum * MAX_R;
          if (r < 0.25) continue;
          dots.push({
            x: pxx, y: py, baseR: r,
            phase: Math.sin(pxx * 0.31 + py * 0.17) * Math.PI,
          });
        }
      }

      loop();
    };
    img.src = 'data:image/png;base64,' + FRESCO_B64;

    function loop() {
      frame++;
      const t = frame * 0.016;

      nextPulse--;
      if (nextPulse <= 0) {
        pulses.push({ r: 0, alpha: 0.5 });
        nextPulse = 360 + Math.floor(Math.random() * 200);
      }
      pulses = pulses
        .map(p => ({ r: p.r + 2.5, alpha: p.alpha * 0.97 }))
        .filter(p => p.alpha > 0.012);

      ctx.fillStyle = '#09090f';
      ctx.fillRect(0, 0, CW, CH);

      for (const p of pulses) {
        const g = ctx.createRadialGradient(CW/2, CH/2, Math.max(0, p.r-14), CW/2, CH/2, p.r);
        g.addColorStop(0,   'rgba(124,58,237,0)');
        g.addColorStop(0.6, `rgba(157,101,255,${(p.alpha*0.5).toFixed(3)})`);
        g.addColorStop(1,   'rgba(124,58,237,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(CW/2, CH/2, p.r, 0, Math.PI*2);
        ctx.fill();
      }

      if (isHover && mouseX > 0) {
        const g = ctx.createRadialGradient(mouseX, mouseY, 0, mouseX, mouseY, 50);
        g.addColorStop(0, 'rgba(124,58,237,0.18)');
        g.addColorStop(1, 'rgba(124,58,237,0)');
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(mouseX, mouseY, 50, 0, Math.PI*2);
        ctx.fill();
      }

      for (const d of dots) {
        let r = d.baseR * (1 + 0.04 * Math.sin(t * 1.3 + d.phase));

        for (const p of pulses) {
          const dist = Math.sqrt((d.x - CW/2)**2 + (d.y - CH/2)**2);
          const wave = Math.abs(dist - p.r);
          if (wave < 18) r *= 1 + (1 - wave/18) * 0.45 * p.alpha * 1.8;
        }

        const hdist = Math.sqrt((d.x - mouseX)**2 + (d.y - mouseY)**2);
        let dotColor: string;
        if (isHover && hdist < 50) {
          const s = 1 - hdist / 50;
          dotColor = `rgba(${Math.round(196-s*72)},${Math.round(190-s*132)},${Math.round(221+s*16)},${(0.7+s*0.3).toFixed(2)})`;
          r *= (1 + s * 0.3);
        } else {
          const v = Math.round(100 + (d.baseR / MAX_R) * 120);
          dotColor = `rgb(${v},${v},${v})`;
        }

        ctx.fillStyle = dotColor;
        ctx.beginPath();
        ctx.arc(d.x, d.y, r, 0, Math.PI*2);
        ctx.fill();
      }

      animId = requestAnimationFrame(loop);
    }

    return () => {
      cancelAnimationFrame(animId);
      canvas.removeEventListener('mousemove', onMove);
      canvas.removeEventListener('mouseenter', onEnter);
      canvas.removeEventListener('mouseleave', onLeave);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className={className}
      style={{ display: 'block', width: '100%', height: '100%', cursor: 'crosshair' }}
    />
  );
}
